export function stateById(id: string): StateData | undefined {
  return STATES_DATA.find((s) => s.id.toLowerCase() === id.toLowerCase());
}

export function stateBySlug(slug: string): StateData | undefined {
  return STATES_DATA.find((s) => s.slug === slug || s.id === slug);
}

export function statesByRegion(region: Region): StateData[] {
  return STATES_DATA.filter((s) => s.region === region);
}

export function allRegions(): Region[] {
  return ["north", "south", "west", "east", "northeast", "central"];
}

